create table if not exists public.exam_blueprints (id uuid primary key default gen_random_uuid(), state_code char(2) not null, license_track text not null, title text not null, source_url text not null, effective_from date, version int not null default 1, status text not null default 'active', sections jsonb not null default '[]'::jsonb, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(state_code,license_track,version));
create table if not exists public.study_guides (id uuid primary key default gen_random_uuid(), course_id uuid not null references public.courses(id) on delete cascade, state_code char(2), title text not null, version int not null default 1, status text not null default 'published', body jsonb not null default '{}'::jsonb, source_snapshot jsonb not null default '[]'::jsonb, validated_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.question_objectives (question_id uuid not null references public.question_bank(id) on delete cascade, blueprint_id uuid not null references public.exam_blueprints(id) on delete cascade, objective_key text not null, source_url text not null, verified_at timestamptz, primary key(question_id,blueprint_id,objective_key));
create table if not exists public.exam_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, state_code char(2) not null, license_track text not null, mode text not null, started_at timestamptz not null default now(), completed_at timestamptz, score_percent numeric, passed boolean, blueprint_version int, weak_topics jsonb not null default '[]'::jsonb, metadata jsonb not null default '{}'::jsonb);
create table if not exists public.exam_session_answers (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.exam_sessions(id) on delete cascade, question_id uuid not null references public.question_bank(id), selected_key text, correct boolean, topic text, answered_at timestamptz not null default now());
-- Production migration also installs RLS and official TX/FL/IL blueprint records and quarantines legacy internal-only questions.